-- Phase 7: quote form posts to the leads API (pages.contact.quoteForm).
-- Adds the sending/error/rate-limit copy and the per-field error copy where
-- missing (values the owner already set win: they are on the right of ||) and
-- replaces sentMessage only while it is still the old mailto seed.
UPDATE "pages"
SET
  "draft" = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set("draft", '{quoteForm}', '{"sendingLabel":"Sending…","errorMessage":"Something went wrong. Please try again, or call us.","rateLimitedMessage":"Too many attempts. Please try again in a few minutes."}'::jsonb || ("draft" -> 'quoteForm') || CASE WHEN "draft" #>> '{quoteForm,sentMessage}' = 'Your email app should open with your request. If it doesn''t, email us at {email}.' THEN jsonb_build_object('sentMessage', 'Thanks, we''ve received your request and will be in touch shortly. You can also email us at {email}.'::text) ELSE '{}'::jsonb END), '{quoteForm,fields,name}', '{"error":"Please enter your name."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,name}', '{}'::jsonb)), '{quoteForm,fields,phone}', '{"error":"Please enter a phone number we can reach you on."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,phone}', '{}'::jsonb)), '{quoteForm,fields,email}', '{"error":"Please enter a valid email address."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,email}', '{}'::jsonb)), '{quoteForm,fields,service}', '{"error":"Please choose a service from the list."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,service}', '{}'::jsonb)), '{quoteForm,fields,address}', '{"error":"Please check your address or Eircode."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,address}', '{}'::jsonb)), '{quoteForm,fields,message}', '{"error":"Please shorten your message."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,message}', '{}'::jsonb)), '{quoteForm,fields,consent}', '{"error":"Please agree to be contacted so we can reply."}'::jsonb || COALESCE("draft" #> '{quoteForm,fields,consent}', '{}'::jsonb)),
  "published" = CASE
    WHEN jsonb_typeof("published" -> 'quoteForm') = 'object'
    THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set("published", '{quoteForm}', '{"sendingLabel":"Sending…","errorMessage":"Something went wrong. Please try again, or call us.","rateLimitedMessage":"Too many attempts. Please try again in a few minutes."}'::jsonb || ("published" -> 'quoteForm') || CASE WHEN "published" #>> '{quoteForm,sentMessage}' = 'Your email app should open with your request. If it doesn''t, email us at {email}.' THEN jsonb_build_object('sentMessage', 'Thanks, we''ve received your request and will be in touch shortly. You can also email us at {email}.'::text) ELSE '{}'::jsonb END), '{quoteForm,fields,name}', '{"error":"Please enter your name."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,name}', '{}'::jsonb)), '{quoteForm,fields,phone}', '{"error":"Please enter a phone number we can reach you on."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,phone}', '{}'::jsonb)), '{quoteForm,fields,email}', '{"error":"Please enter a valid email address."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,email}', '{}'::jsonb)), '{quoteForm,fields,service}', '{"error":"Please choose a service from the list."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,service}', '{}'::jsonb)), '{quoteForm,fields,address}', '{"error":"Please check your address or Eircode."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,address}', '{}'::jsonb)), '{quoteForm,fields,message}', '{"error":"Please shorten your message."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,message}', '{}'::jsonb)), '{quoteForm,fields,consent}', '{"error":"Please agree to be contacted so we can reply."}'::jsonb || COALESCE("published" #> '{quoteForm,fields,consent}', '{}'::jsonb))
    ELSE "published"
  END
WHERE "key" = 'contact' AND jsonb_typeof("draft" -> 'quoteForm') = 'object';
--> statement-breakpoint
UPDATE "revisions"
SET "data" = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set("data", '{quoteForm}', '{"sendingLabel":"Sending…","errorMessage":"Something went wrong. Please try again, or call us.","rateLimitedMessage":"Too many attempts. Please try again in a few minutes."}'::jsonb || ("data" -> 'quoteForm') || CASE WHEN "data" #>> '{quoteForm,sentMessage}' = 'Your email app should open with your request. If it doesn''t, email us at {email}.' THEN jsonb_build_object('sentMessage', 'Thanks, we''ve received your request and will be in touch shortly. You can also email us at {email}.'::text) ELSE '{}'::jsonb END), '{quoteForm,fields,name}', '{"error":"Please enter your name."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,name}', '{}'::jsonb)), '{quoteForm,fields,phone}', '{"error":"Please enter a phone number we can reach you on."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,phone}', '{}'::jsonb)), '{quoteForm,fields,email}', '{"error":"Please enter a valid email address."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,email}', '{}'::jsonb)), '{quoteForm,fields,service}', '{"error":"Please choose a service from the list."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,service}', '{}'::jsonb)), '{quoteForm,fields,address}', '{"error":"Please check your address or Eircode."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,address}', '{}'::jsonb)), '{quoteForm,fields,message}', '{"error":"Please shorten your message."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,message}', '{}'::jsonb)), '{quoteForm,fields,consent}', '{"error":"Please agree to be contacted so we can reply."}'::jsonb || COALESCE("data" #> '{quoteForm,fields,consent}', '{}'::jsonb))
WHERE "entity_type" = 'page' AND "entity_id" = 'contact' AND jsonb_typeof("data" -> 'quoteForm') = 'object';
